create or replace function public.create_check_in(p_place_id uuid,p_qr_token text default null) returns jsonb language plpgsql security definer set search_path=public,auth,extensions,pg_temp as $$ declare v_user uuid:=auth.uid();v_location uuid;v_business uuid;v_check uuid;v_points integer:=10;v_existing uuid;v_qr uuid;begin if v_user is null then raise exception 'Authentication required';end if; select p.location_id,l.business_id into v_location,v_business from public.places p join public.locations l on l.id=p.location_id where p.id=p_place_id and p.is_active=true and l.is_active=true; if v_location is null then raise exception 'Place not found';end if; if p_qr_token is not null and length(trim(p_qr_token))>0 then select id into v_qr from public.qr_codes where code=trim(p_qr_token) and active=true and location_id=v_location limit 1; if v_qr is null then raise exception 'Invalid or inactive QR code';end if; end if; select id into v_existing from public.check_ins where user_id=v_user and location_id=v_location and checked_in_at>now()-interval '24 hours' order by checked_in_at desc limit 1; if v_existing is not null then return jsonb_build_object('ok',true,'already_checked_in',true,'check_in_id',v_existing,'id',v_existing,'location_id',v_location,'business_id',v_business,'qr_code_id',v_qr,'points_awarded',0,'place_id',p_place_id);end if; insert into public.check_ins(user_id,location_id,qr_code_id,checked_in_at,verification_method,points_awarded,metadata) values(v_user,v_location,v_qr,now(),case when v_qr is null then 'place' else 'qr' end,v_points,jsonb_build_object('place_id',p_place_id,'server_authoritative',true)) on conflict do nothing returning id into v_check; if v_check is null then select id into v_check from public.check_ins where user_id=v_user and location_id=v_location and checked_in_at>now()-interval '24 hours' order by checked_in_at desc limit 1; return jsonb_build_object('ok',true,'already_checked_in',true,'check_in_id',v_check,'location_id',v_location,'business_id',v_business,'qr_code_id',v_qr,'points_awarded',0,'place_id',p_place_id);end if; return jsonb_build_object('ok',true,'already_checked_in',false,'check_in_id',v_check,'id',v_check,'location_id',v_location,'business_id',v_business,'qr_code_id',v_qr,'points_awarded',v_points,'place_id',p_place_id);end $$;

create or replace function public.record_qr_attribution(p_code text,p_action_type text default 'scan',p_source text default null,p_metadata jsonb default '{}'::jsonb) returns uuid language plpgsql security definer set search_path=public,auth,extensions,pg_temp as $$ declare v_qr public.qr_codes;v_id uuid;v_business uuid;v_location uuid;begin if auth.uid() is null then raise exception 'Authentication required';end if;if nullif(trim(p_code),'') is null then raise exception 'QR code is required';end if;select * into v_qr from public.qr_codes where code=trim(p_code) and coalesce(active,true) limit 1;if not found then raise exception 'QR code not found or inactive';end if;v_location:=v_qr.location_id;select business_id into v_business from public.locations where id=v_location;insert into public.qr_attribution_events(qr_code_id,location_id,business_id,user_id,action_type,source,metadata) values(v_qr.id,v_location,v_business,auth.uid(),coalesce(nullif(trim(p_action_type),''),'scan'),p_source,coalesce(p_metadata,'{}'::jsonb)) on conflict do nothing returning id into v_id;if v_id is null then select id into v_id from public.qr_attribution_events where qr_code_id=v_qr.id and user_id=auth.uid() and action_type=coalesce(nullif(trim(p_action_type),''),'scan') and created_at>now()-interval '1 minute' order by created_at desc limit 1;end if;return v_id;end $$;
